class Solution:
    def possible(self, s):
        v = "aeiou"
        if s[0] in v and s[-1] in v:
            return True
        return False
    def vowelStrings(self, words: List[str], queries: List[List[int]]) -> List[int]:
        pos = [0]
        for i in range(len(words)):
            if self.possible(words[i]):
                pos.append(pos[i] + 1)
            else:
                pos.append(pos[i])
        ans = []
        for l, r in queries:
            ans.append(pos[r+1]-pos[l])
        return ans

class Solution:
    def maxScore(self, s: str) -> int:
        zeros = s.count("0")
        maax, ones = 0, 0
        for i in range(len(s)-1, 0, -1):
            if s[i] == "0":
                zeros -= 1
            if s[i] == "1":
                ones += 1
            maax = max(maax, zeros+ones)
        return maax

class Solution:
    def xorAllNums(self, nums1: List[int], nums2: List[int]) -> int:
        return len(nums1)%2 * reduce(xor, nums2) ^ (len(nums2)%2 * reduce(xor, nums1))
